contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address recipient) public payable {
        require(recipient != address(0), "recipient must be nonzero");

        // Fund c so that a successful withdrawal moves a nonzero amount.
        // This contract is the only caller of c, and it deployed c, so msg.sender == address(this).
        // The ETH sent here stays in this contract until forwarded to c.

        // Snapshot before-values via c's public surface.
        address ownerBefore = c.owner();
        uint256 cBalanceBefore = address(c).balance;
        bool callerIsOwner = (ownerBefore == address(this));

        // Flat, top-level deciding call wrapped only at the call site:
        // succeed/fail flag is captured without branching around the call.
        bool reverted;
        try c.withdrawAll(recipient) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after-balance once, flat.
        uint256 cBalanceAfter = address(c).balance;

        // General rule:
        // - If the caller (this contract) is c's owner, withdrawal must not revert and c's balance must be zero.
        // - If the caller is not the owner, withdrawal must revert and c's balance must be unchanged.
        assert(
            (callerIsOwner && !reverted && cBalanceAfter == 0) ||
            (!callerIsOwner && reverted && cBalanceAfter == cBalanceBefore)
        );
    }

    receive() external payable {}
